import{_ as n,o as t,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Governance-Rahmen und Gewaltenbalance","description":"","frontmatter":{},"headers":[],"relativePath":"de/49-治理框架与权力制衡.md","filePath":"de/49-治理框架与权力制衡.md","lastUpdated":null}'),s={name:"de/49-治理框架与权力制衡.md"};function a(d,e,u,l,h,g){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="governance-rahmen-und-gewaltenbalance" tabindex="-1">Governance-Rahmen und Gewaltenbalance <a class="header-anchor" href="#governance-rahmen-und-gewaltenbalance" aria-label="Permalink to &quot;Governance-Rahmen und Gewaltenbalance&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>49</td></tr><tr><td>Modul</td><td>Rechtssystem und Governance-Rahmen</td></tr><tr><td>Kernschlüsselwörter</td><td>Gewaltenteilung, Gewaltenbalance, Anker-Rat, Aufsichtsausschuss, Symbiose-Governance</td></tr></tbody></table><h2 id="i-gesamtentwurf-des-governance-rahmens" tabindex="-1">I. Gesamtentwurf des Governance-Rahmens <a class="header-anchor" href="#i-gesamtentwurf-des-governance-rahmens" aria-label="Permalink to &quot;I. Gesamtentwurf des Governance-Rahmens&quot;">​</a></h2><p>Der Governance-Rahmen der Anker-Symbiose-Zivilisation nimmt die 《Symbiose-Verfassung》 als grundlegende Grundlage und wendet die Governance-Struktur der &quot;Trennung der drei Gewalten, Balance der vier Gewalten&quot; an. Die drei Gewalten beziehen sich auf die Gesetzgebungsgewalt, die Exekutivgewalt und die Justizgewalt, die jeweils vom Anker-Rat, dem Symbiose-Exekutivkomitee und dem Symbiose-Gericht ausgeübt werden; die vierte Gewalt ist die Aufsichtsgewalt, die vom unabhängigen Anker-Aufsichtsausschuss ausgeübt wird und eine umfassende Aufsicht über die drei Gewalten durchführt. Das zentrale Ziel dieser Struktur ist es, die Konzentration und den Missbrauch von Macht zu verhindern und den Boden der räuberischen Governance auf institutioneller Ebene zu beseitigen.</p><p>Der Entwurf des Governance-Rahmens folgt folgenden Prinzipien:</p><table tabindex="0"><thead><tr><th>Prinzip</th><th>Inhalt</th></tr></thead><tbody><tr><td>Prinzip der Gewaltenteilung</td><td>Die drei Gewalten Legislative, Exekutive und Judikative werden jeweils von verschiedenen Organen ausgeübt und dürfen nicht kumuliert werden</td></tr><tr><td>Prinzip der Gewaltenbalance</td><td>Jedes Machtorgan beschränkt und überwacht sich gegenseitig und verhindert, dass eine Seite übermäßige Macht hat</td></tr><tr><td>Prinzip der Beteiligung aller Rassen</td><td>Die Zusammensetzung der Governance-Organe muss die Repräsentativität aller Rassen widerspiegeln und sicherstellen, dass jede Rasse an öffentlichen Angelegenheiten teilnehmen kann</td></tr><tr><td>Prinzip der demokratischen Konzentration</td><td>Wichtige Entscheidungen werden nach ausführlicher demokratischer Diskussion konzentriert entschieden, wobei sowohl Effizienz als auch Demokratie berücksichtigt werden</td></tr><tr><td>Prinzip der Basisautonomie</td><td>Basisangelegenheiten werden von Basisautonomieorganisationen verwaltet, und übergeordnete Organe dürfen nicht übermäßig eingreifen</td></tr><tr><td>Prinzip der transparenten Governance</td><td>Der Governance-Prozess und die Entscheidungsinformationen werden nach Gesetz veröffentlicht und unterliegen der öffentlichen Aufsicht</td></tr></tbody></table><h2 id="ii-gesetzgebungsgewalt-anker-rat" tabindex="-1">II. Gesetzgebungsgewalt: Anker-Rat <a class="header-anchor" href="#ii-gesetzgebungsgewalt-anker-rat" aria-label="Permalink to &quot;II. Gesetzgebungsgewalt: Anker-Rat&quot;">​</a></h2><p>Der Anker-Rat ist das höchste Machtorgan der Anker-Symbiose-Zivilisation und übt die Gesetzgebungsgewalt und die Entscheidungsgewalt über wichtige Angelegenheiten aus.</p><h3 id="_1-zusammensetzung-und-entstehung" tabindex="-1">(1) Zusammensetzung und Entstehung <a class="header-anchor" href="#_1-zusammensetzung-und-entstehung" aria-label="Permalink to &quot;(1) Zusammensetzung und Entstehung&quot;">​</a></h3><ul><li><strong>Zusammensetzung der Vertreter</strong>: Der Anker-Rat besteht aus Vertretern aller Rassen proportional, wobei Vertreter der Menschenrasse 30% der Gesamtzahl nicht überschreiten, und die übrigen Sitze werden nach Bevölkerungsgröße und Beitragsgrad jeder Rasse verteilt.</li><li><strong>Amtszeit der Vertreter</strong>: Die Amtszeit der Ratsvertreter beträgt fünf Jahre, und sie können wiedergewählt werden, aber die Wiederwahl darf drei Amtszeiten nicht überschreiten.</li><li><strong>Wahlmethode</strong>: Die Vertreter werden durch demokratische Wahlen innerhalb jeder Rasse gewählt, wobei der Wahlprozess offen und transparent ist und der Aufsicht unterliegt.</li><li><strong>Ständiges Organ</strong>: Während der Sitzungsperiode des Rates übt der Ständige Ausschuss einen Teil der Befugnisse aus, und die Mitglieder des Ständigen Ausschusses werden aus den Vertretern gewählt.</li></ul><h3 id="_2-zustandigkeitsbereich" tabindex="-1">(2) Zuständigkeitsbereich <a class="header-anchor" href="#_2-zustandigkeitsbereich" aria-label="Permalink to &quot;(2) Zuständigkeitsbereich&quot;">​</a></h3><ol><li><strong>Gesetzgebungsgewalt</strong>: Verfassung, Grundgesetze und andere wichtige Gesetze erlassen und ändern.</li><li><strong>Entscheidungsgewalt über wichtige Angelegenheiten</strong>: Entscheidungen über Zivilisationsentwicklungspläne, Jahreshaushalt, Krieg und Frieden, Ebenenentwicklung und andere wichtige Angelegenheiten treffen.</li><li><strong>Personalernennungs- und Entlassungsgewalt</strong>: Den Vorsitzenden des Symbiose-Exekutivkomitees, den Präsidenten des Symbiose-Gerichts, den Direktor des Anker-Aufsichtsausschusses und andere Hauptbeamte wählen und abberufen.</li><li><strong>Aufsichtsgewalt</strong>: Die Arbeit des Symbiose-Exekutivkomitees und des Symbiose-Gerichts überwachen, Arbeitsberichte anhören und beraten.</li><li><strong>Verfassungsänderungsgewalt</strong>: Die Verfassungsänderung erfordert die Annahme durch eine Mehrheit von mehr als zwei Dritteln und ein Volksreferendum.</li></ol><h3 id="_3-beratungsregeln" tabindex="-1">(3) Beratungsregeln <a class="header-anchor" href="#_3-beratungsregeln" aria-label="Permalink to &quot;(3) Beratungsregeln&quot;">​</a></h3><ul><li>Der Rat hält einmal jährlich eine Plenarsitzung ab und kann bei Bedarf außerordentliche Sitzungen einberufen.</li><li>Die Beratung von Gesetzesentwürfen wendet das System der &quot;drei Lesungen&quot; an: Die erste Lesung berät die Gesetzgebungsnotwendigkeit, die zweite Lesung berät den Inhalt der Artikel, und die dritte Lesung stimmt zur Annahme ab.</li><li>Die Abstimmung wendet eine Person eine Stimme an, wobei allgemeine Gesetze mit einfacher Mehrheit angenommen werden und Verfassungsänderungen mit einer Mehrheit von mehr als zwei Dritteln angenommen werden.</li><li>Der Beratungsprozess wird öffentlich durchgeführt, wobei die Teilnahme der Öffentlichkeit als Zuhörer und die Berichterstattung durch die Medien erlaubt sind.</li></ul><h2 id="iii-exekutivgewalt-symbiose-exekutivkomitee" tabindex="-1">III. Exekutivgewalt: Symbiose-Exekutivkomitee <a class="header-anchor" href="#iii-exekutivgewalt-symbiose-exekutivkomitee" aria-label="Permalink to &quot;III. Exekutivgewalt: Symbiose-Exekutivkomitee&quot;">​</a></h2><p>Das Symbiose-Exekutivkomitee ist das höchste Exekutivorgan der Anker-Symbiose-Zivilisation und ist für die Durchführung der Verfassung und der Gesetze sowie für die tägliche Governance verantwortlich.</p><h3 id="_1-zusammensetzung-und-entstehung-1" tabindex="-1">(1) Zusammensetzung und Entstehung <a class="header-anchor" href="#_1-zusammensetzung-und-entstehung-1" aria-label="Permalink to &quot;(1) Zusammensetzung und Entstehung&quot;">​</a></h3><ul><li><strong>Vorsitzsystem</strong>: Das Symbiose-Exekutivkomitee wendet das Verantwortungssystem des Vorsitzenden an, und der Vorsitzende ist der Regierungschef, der vom Anker-Rat gewählt wird, mit einer Amtszeit von fünf Jahren, und kann einmal wiedergewählt werden.</li><li><strong>Zusammensetzung der Mitglieder</strong>: Das Komitee besteht aus dem Vorsitzenden, den stellvertretenden Vorsitzenden und den Leitern jeder Abteilung, wobei die Leiter jeder Abteilung vom Vorsitzenden nominiert und vom Rat ernannt werden.</li><li><strong>Quote für fremde Rassen</strong>: Der Anteil fremder Rassen unter den Komiteemitgliedern beträgt nicht weniger als 40%, wodurch sichergestellt wird, dass Verwaltungsentscheidungen die Interessen jeder Rasse berücksichtigen.</li></ul><h3 id="_2-zustandigkeitsbereich-1" tabindex="-1">(2) Zuständigkeitsbereich <a class="header-anchor" href="#_2-zustandigkeitsbereich-1" aria-label="Permalink to &quot;(2) Zuständigkeitsbereich&quot;">​</a></h3><ol><li><strong>Administrative Gesetzgebungsgewalt</strong>: Verwaltungsvorschriften, Regeln und Richtlinien auf der Grundlage der Verfassung und der Gesetze erlassen.</li><li><strong>Verwaltungsverwaltungsgewalt</strong>: Verschiedene Verwaltungsarbeiten wie Wirtschaft, Bildung, Wissenschaft, Kultur, Gesundheit, Sport, Umwelt usw. leiten und verwalten.</li><li><strong>Personalverwaltungsgewalt</strong>: Verwaltungspersonal nach gesetzlichen Bestimmungen ernennen, ausbilden, bewerten und belohnen/bestrafen.</li><li><strong>Diplomatische Gewalt</strong>: Die Symbiose-Zivilisation bei inter-ebenen diplomatischen Aktivitäten vertreten und Verträge und Abkommen schließen.</li><li><strong>Notstandsbefugnis</strong>: Bei schwerwiegenden unerwarteten Ereignissen kann nach Gesetz der Notstand ausgerufen und Notmaßnahmen ergriffen werden, dies muss jedoch innerhalb der vorgeschriebenen Frist zur Genehmigung an den Rat gemeldet werden.</li></ol><h3 id="_3-einrichtung-der-verwaltungsabteilungen" tabindex="-1">(3) Einrichtung der Verwaltungsabteilungen <a class="header-anchor" href="#_3-einrichtung-der-verwaltungsabteilungen" aria-label="Permalink to &quot;(3) Einrichtung der Verwaltungsabteilungen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Abteilung</th><th>Hauptfunktionen</th></tr></thead><tbody><tr><td>Abteilung für Symbiose-Entwicklung</td><td>Zivilisationsentwicklungspläne erlassen, die Entwicklung verschiedener Bereiche koordinieren</td></tr><tr><td>Abteilung für Ressourcenverwaltung</td><td>Kultivierungsressourcen und öffentliche Ressourcen verwalten, den Mechanismus des gemeinsamen Produktionsvertrags implementieren</td></tr><tr><td>Abteilung für Bildung und Kultur</td><td>Bildungswesen und kulturelle Angelegenheiten verwalten</td></tr><tr><td>Abteilung für Gesundheit und Medizin</td><td>Gesundheits- und Medizinwesen sowie öffentliche Gesundheit verwalten</td></tr><tr><td>Abteilung für Ökologie und Umwelt</td><td>Umweltschutz und ökologischen Aufbau verwalten</td></tr><tr><td>Abteilung für Ebenenangelegenheiten</td><td>Ebenenentwicklung und inter-ebenen Angelegenheiten verwalten</td></tr><tr><td>Abteilung für Angelegenheiten aller Rassen</td><td>Beziehungen aller Rassen koordinieren, Angelegenheiten fremder Rassen bearbeiten</td></tr><tr><td>Abteilung für Finanzen und Wirtschaft</td><td>Haushalt und Wirtschaftsbetrieb verwalten</td></tr><tr><td>Abteilung für Sicherheit</td><td>Öffentliche Sicherheit und Zivilisationssicherheit wahren</td></tr></tbody></table><h2 id="iv-justizgewalt-symbiose-gericht" tabindex="-1">IV. Justizgewalt: Symbiose-Gericht <a class="header-anchor" href="#iv-justizgewalt-symbiose-gericht" aria-label="Permalink to &quot;IV. Justizgewalt: Symbiose-Gericht&quot;">​</a></h2><p>Das Symbiose-Gericht ist das höchste Justizorgan der Anker-Symbiose-Zivilisation und übt unabhängig die Gerichtsbarkeit aus. Sein Organisationssystem, Prozessverfahren und System der Verfassungsüberprüfung sind im 《48-Justizsystem und Entscheidungsmechanismus》 detailliert dargelegt.</p><p>Im Rahmen der Gewaltenbalance manifestiert sich die Beschränkung der Justizgewalt gegenüber der Gesetzgebungsgewalt und der Exekutivgewalt in:</p><ol><li><strong>Verfassungsüberprüfungsgewalt</strong>: Das Symbiose-Gericht hat die Befugnis, Gesetze und Verwaltungsvorschriften, die gegen die Verfassung verstoßen, für ungültig zu erklären.</li><li><strong>Verwaltungsgerichtsbarkeit</strong>: Das Gericht hat die Befugnis, Verwaltungsverfahren zu verhandeln und die Rechtmäßigkeit von Verwaltungsakten zu überprüfen.</li><li><strong>Amtsgerichtsbarkeit</strong>: Die vom Rat eingereichten Amtsverfahren gegen hohe Beamte werden vom Symbiose-Gericht verhandelt.</li></ol><p>Gleichzeitig wird die Justizgewalt auch durch die Gesetzgebungsgewalt und die Exekutivgewalt beschränkt: Die Richter werden vom Rat ernannt, der Justizetat wird von der Verwaltungsabteilung erstellt (muss jedoch vom Rat genehmigt werden und darf von der Verwaltungsbehörde nicht gekürzt werden), und der Anker-Aufsichtsausschuss überwacht die Justiztätigkeit.</p><h2 id="v-aufsichtsgewalt-anker-aufsichtsausschuss" tabindex="-1">V. Aufsichtsgewalt: Anker-Aufsichtsausschuss <a class="header-anchor" href="#v-aufsichtsgewalt-anker-aufsichtsausschuss" aria-label="Permalink to &quot;V. Aufsichtsgewalt: Anker-Aufsichtsausschuss&quot;">​</a></h2><p>Der Anker-Aufsichtsausschuss ist ein unabhängiges Aufsichtsorgan und übt die vierte Gewalt - die Aufsichtsgewalt aus, die eine umfassende Aufsicht über alle Machtorgane durchführt.</p><h3 id="_1-zusammensetzung-und-entstehung-2" tabindex="-1">(1) Zusammensetzung und Entstehung <a class="header-anchor" href="#_1-zusammensetzung-und-entstehung-2" aria-label="Permalink to &quot;(1) Zusammensetzung und Entstehung&quot;">​</a></h3><ul><li><strong>Direktorverantwortungssystem</strong>: Der Aufsichtsausschuss wendet das Verantwortungssystem des Direktors an, und der Direktor wird vom Anker-Rat gewählt, mit einer Amtszeit von fünf Jahren, und kann nicht wiedergewählt werden.</li><li><strong>Zusammensetzung der Mitglieder</strong>: Die Ausschussmitglieder bestehen aus Vertretern aller Rassen, Rechtsexperten und Vertretern der Öffentlichkeit, wobei die Vollzeitmitglieder nicht weniger als die Hälfte betragen.</li><li><strong>Unabhängigkeitsgarantie</strong>: Der Haushalt des Aufsichtsausschusses wird unabhängig ausgewiesen, und die Mitglieder dürfen ohne gesetzliche Gründe nicht entlassen werden, wodurch die Unabhängigkeit der Aufsicht gewährleistet wird.</li></ul><h3 id="_2-zustandigkeitsbereich-2" tabindex="-1">(2) Zuständigkeitsbereich <a class="header-anchor" href="#_2-zustandigkeitsbereich-2" aria-label="Permalink to &quot;(2) Zuständigkeitsbereich&quot;">​</a></h3><ol><li><strong>Integritätsaufsicht</strong>: Die Integrität und Selbstdisziplin aller öffentlichen Beamten überwachen, Korruption, Bestechung, Machtmissbrauch zu privaten Zwecken usw. untersuchen und bestrafen.</li><li><strong>Effizienzaufsicht</strong>: Die Arbeitseffizienz jedes Machtorgans überwachen, Untätigkeit, willkürliches Handeln, langsames Handeln usw. untersuchen und bestrafen.</li><li><strong>Rechtsdurchsetzungsaufsicht</strong>: Die Durchführung der Gesetze überwachen, Nichteinhaltung des Gesetzes, nicht strenge Rechtsdurchsetzung, Nichtverfolgung rechtswidriger Handlungen usw. untersuchen und bestrafen.</li><li><strong>Finanzaufsicht</strong>: Die Verwendung der öffentlichen Finanzen überwachen, Verschwendung öffentlicher Ressourcen, Unterschlagung öffentlicher Gelder usw. untersuchen und bestrafen.</li><li><strong>Räuberische Handlungsaufsicht</strong>: Insbesondere die Wiederkehr räuberischer Handlungen überwachen, Handlungen untersuchen und bestrafen, die Macht zur Räuberei nutzen.</li></ol><h3 id="_3-aufsichtsmethoden" tabindex="-1">(3) Aufsichtsmethoden <a class="header-anchor" href="#_3-aufsichtsmethoden" aria-label="Permalink to &quot;(3) Aufsichtsmethoden&quot;">​</a></h3><ul><li>Tägliche Aufsicht: Tägliche Aufsicht durch Inspektionen, Prüfungen, Audits usw. durchführen.</li><li>Sonderaufsicht: Sonderaufsicht针对 bestimmte Bereiche oder bestimmte Probleme durchführen.</li><li>Eingang von Beschwerden: Beschwerden und Klagen der Öffentlichkeit über rechtswidrige und disziplinarwidrige Handlungen entgegennehmen.</li><li>Untersuchung und Verantwortung: Den Verdacht auf rechtswidrige und disziplinarwidrige Handlungen untersuchen und Verantwortungsvorschläge unterbreiten.</li><li>Öffentliche Mitteilung: Regelmäßig die Aufsichtssituation und typische Fälle veröffentlichen und der sozialen Aufsicht unterliegen.</li></ul><h2 id="vi-mechanismus-der-gewaltenbalance" tabindex="-1">VI. Mechanismus der Gewaltenbalance <a class="header-anchor" href="#vi-mechanismus-der-gewaltenbalance" aria-label="Permalink to &quot;VI. Mechanismus der Gewaltenbalance&quot;">​</a></h2><p>Die Balancebeziehungen zwischen jedem Machtorgan sind in der folgenden Tabelle dargestellt:</p><table tabindex="0"><thead><tr><th>Balancebeziehung</th><th>Balancenmethode</th></tr></thead><tbody><tr><td>Gesetzgebungsgewalt beschränkt Exekutivgewalt</td><td>Der Rat hat die Befugnis, den Exekutivvorsitzenden abzuberufen, Verwaltungsvorschläge abzulehnen, Haushalte zu genehmigen</td></tr><tr><td>Gesetzgebungsgewalt beschränkt Justizgewalt</td><td>Der Rat hat die Befugnis, Richter zu ernennen, das Gerichtsorganisationsgesetz zu ändern, Richter anzuklagen</td></tr><tr><td>Exekutivgewalt beschränkt Gesetzgebungsgewalt</td><td>Der Exekutivvorsitzende hat die Befugnis, vom Rat verabschiedete Gesetze einzuveto (der Rat kann das Veto mit einer Mehrheit von mehr als zwei Dritteln aufheben)</td></tr><tr><td>Exekutivgewalt beschränkt Justizgewalt</td><td>Die Verwaltungsabteilung ist für die Vollstreckung von Gerichtsurteilen verantwortlich und verwaltet Justizverwaltungsangelegenheiten</td></tr><tr><td>Justizgewalt beschränkt Gesetzgebungsgewalt</td><td>Das Gericht hat die Befugnis, Verfassungsüberprüfung durchzuführen und Gesetze für ungültig zu erklären</td></tr><tr><td>Justizgewalt beschränkt Exekutivgewalt</td><td>Das Gericht hat die Befugnis, Verwaltungsverfahren zu verhandeln und die Rechtmäßigkeit von Verwaltungsakten zu überprüfen</td></tr><tr><td>Aufsichtsgewalt beschränkt die drei Gewalten</td><td>Der Aufsichtsausschuss führt eine umfassende Aufsicht über die drei Gewalten Legislative, Exekutive und Judikative durch</td></tr><tr><td>Die drei Gewalten beschränken die Aufsichtsgewalt</td><td>Der Rat ernennt den Direktor des Aufsichtsausschusses, und das Gericht verhandelt rechtswidrige Handlungen des Aufsichtsausschusses</td></tr></tbody></table><h2 id="vii-basis-governance-und-autonomie" tabindex="-1">VII. Basis-Governance und Autonomie <a class="header-anchor" href="#vii-basis-governance-und-autonomie" aria-label="Permalink to &quot;VII. Basis-Governance und Autonomie&quot;">​</a></h2><p>Unter dem zentralen Governance-Rahmen wird das System der Basisautonomie angewendet:</p><ul><li><strong>Gemeinde-/Dorfautonomie</strong>: Basisgemeinden und Dörfer wenden die Bewohnerautonomie an, wählen durch Bewohnerversammlungen Autonomieorganisationen, um lokale öffentliche Angelegenheiten zu verwalten.</li><li><strong>Ebenenautonomie</strong>: Jede Ebene genießt unter der Voraussetzung der Einhaltung von Verfassung und Gesetzen eine gewisse Autonomie und kann nach lokalen Gegebenheiten Durchführungsbestimmungen erlassen.</li><li><strong>Rassenautonomie</strong>: Die Siedlungsgebiete jeder Rasse können Rassenautonomieorganisationen errichten, um interne Angelegenheiten der eigenen Rasse zu verwalten, dies darf jedoch nicht gegen Verfassung und Gesetze verstoßen.</li><li><strong>Branchenautonomie</strong>: Jede Branche kann Branchenverbände errichten, um Branchenselbstdisziplin und Branchenverwaltung durchzuführen.</li></ul><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Der Governance-Rahmen und die Gewaltenbalance sind die institutionelle Garantie für die langfristige Stabilität der Anker-Symbiose-Zivilisation. Durch den Strukturentwurf der &quot;Trennung der drei Gewalten, Balance der vier Gewalten&quot;, das Repräsentativsystem der Beteiligung aller Rassen und das Governance-Modell der Basisautonomie wird sichergestellt, dass Macht im Sonnenlicht operiert, die Konzentration von Macht und die Wiederkehr der räuberischen Governance verhindert werden, und ein stabiles, gerechtes und effizientes Governance-System für den gemeinsamen Fortschritt aller Rassen bereitgestellt wird.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Allgemeine Grundsätze der Symbiose-Verfassung)</li><li>48-司法体系与裁决机制 (Justizsystem und Entscheidungsmechanismus)</li><li>03-共生文明宪章 (Charta der Symbiose-Zivilisation)</li><li>36-社会结构与阶层流动 (Sozialstruktur und Schichtenmobilität)</li></ul>',45)])])}const b=n(s,[["render",a]]);export{c as __pageData,b as default};
